solutionCode:
pub fn tema(escuro: bool) -> String {
    if escuro {
        String::from("tema escuro")
    } else {
        String::from("tema claro")
    }
}

testsCode:
use desafio::tema;

#[test]
fn testa_o_tema_escuro() {
    assert_eq!(tema(true), "tema escuro");
}

#[test]
fn testa_o_tema_claro() {
    assert_eq!(tema(false), "tema claro");
}
